		await expect(executor.execute({
			toolName: "generate_image", arguments: { prompt: "owl" },
			context: { ...trustedText, confirmationToken: valid.id }, run: async () => ++runs,
		})).rejects.toMatchObject({ outcome: "deny" });
		expect(runs).toBe(1);
	});

