						{isMultiBlankFillIn ? (
							<div className={shared.minFlex}>
								<MultiBlankFillIn
									question={displayQuestion}
									blanks={q.blanks ?? []}
									answer={answer}
									onChange={onChange}
									revealed={revealed}
									correctAnswers={q.correctAnswers ?? [q.correctAnswer]}
								/>
							</div>
						) : (
							<p className={css({ minWidth: 0, flex: 1, fontSize: "0.875rem", fontWeight: 500, lineHeight: "1.5rem" })}>{displayQuestion}</p>
						)}
						{revealed && showsBinaryResult(q) && <QuizResultBadge correct={binaryCorrect} />}
					</div>
					{reframeModes.length > 0 && !revealed && onReframe && (
						<ReframeToggle
							modes={reframeModes}
