export function isOpenEnded(q: QuizQuestion): boolean {
	if (q.type === "short_answer" || q.type === "transfer") return true;
	// Single-blank fill_in is free text; multi-blank fill_in is graded per blank.
	if (q.type === "fill_in" && !(q.blanks && q.blanks.length > 0)) return true;
	return false;
}

function isCorrect(q: QuizQuestion, rawAnswer: string): boolean {
	if (q.type === "multi_select" && q.correctAnswers) {
		const selected = new Set(rawAnswer.split(",").map((s) => s.trim()).filter(Boolean));
		return (
			q.correctAnswers.length === selected.size &&
			q.correctAnswers.every((c) => selected.has(c))
		);
	}
	if (q.type === "fill_in" && q.blanks && q.blanks.length > 0) {
		const userAnswers = rawAnswer.split("|").map((s) => s.trim());
		const correctAnswers = q.correctAnswers ?? [q.correctAnswer];
		if (userAnswers.length !== correctAnswers.length) return false;
		return userAnswers.every((a, i) => a.toLowerCase() === correctAnswers[i].trim().toLowerCase());
	}
	if (isOpenEnded(q)) {
		return questionCredit(q, rawAnswer) >= OPEN_ENDED_CREDIT_THRESHOLD;
	}
	return rawAnswer.trim().toLowerCase() === q.correctAnswer.trim().toLowerCase();
}

function QuizOption({
	label,
	selected,
	onClick,
	disabled,
	status,
	checkbox,
}: {
	label: string;
	selected: boolean;
	onClick: () => void;
	disabled?: boolean;
	status?: "correct" | "wrong" | "neutral";
	checkbox?: boolean;
}) {
	const stateClass =
		status === "correct"
			? quizStyles.optionCorrect
			: status === "wrong"
				? quizStyles.optionWrong
				: selected
					? quizStyles.optionSelected
					: quizStyles.optionNeutral;
	return (
		<button
			type="button"
			className={cx(quizStyles.optionBase, stateClass, disabled && quizStyles.disabled)}
			onClick={onClick}
			disabled={disabled}
			aria-pressed={selected}
		>
			{checkbox ? (
				<span
					className={cx(
						quizStyles.checkboxBase,
						selected ? quizStyles.checkboxSelected : quizStyles.checkboxNeutral,
					)}
				>
					{selected ? <Check size={12} /> : null}
				</span>
			) : status === "correct" ? (
				<CheckCircle2 size={16} />
			) : status === "wrong" ? (
				<XCircle size={16} />
			) : selected ? (
				<CheckCircle2 size={16} />
			) : (
				<Circle size={16} />
			)}
			<span className={css({ minWidth: 0, flex: 1, overflowWrap: "anywhere" })}>{label}</span>
		</button>
	);
}

function QuestionTimer({
	seconds,
	warningAt = 5,
}: {
	seconds: number;
	warningAt?: number;
}) {
	const display = formatCountdown(seconds);
	const urgent = seconds <= warningAt;
	return (
		<span
			className={cx(
				"font-terminal",
				css({
					display: "inline-flex",
					alignItems: "center",
					gap: "0.25rem",
					fontSize: "0.875rem",
					fontVariantNumeric: "tabular-nums",
					color: urgent ? "var(--destructive)" : "var(--muted-foreground)",
					animation: urgent ? "pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite" : undefined,
				}),
			)}
		>
			<Clock size={14} />
			{display}
		</span>
	);
}

